import numpy as np
import pandas as pd


def _rank_centered(s):
    s = pd.Series(s, dtype=float)
    s = s.replace([np.inf, -np.inf], np.nan)
    return s.rank(pct=True) - 0.5


def _last_completed_month_end(idx):
    if len(idx) == 0:
        return None
    ym = idx.year * 100 + idx.month
    is_me = np.zeros(len(idx), dtype=bool)
    if len(idx) > 1:
        is_me[:-1] = ym[1:] != ym[:-1]
    me = idx[is_me]
    if len(me) == 0:
        return None
    return me[-1]


def generate_weights(history, universe):
    universe = pd.Index(universe)
    zeros = pd.Series(0.0, index=universe, dtype=float)

    cl = history.get('adjusted_close')
    if cl is None or getattr(cl, 'shape', (0, 0))[1] == 0:
        cl = history.get('close')
    if cl is None or getattr(cl, 'shape', (0, 0))[1] == 0:
        return zeros

    try:
        cl = cl.reindex(columns=universe).astype(float)
    except Exception:
        return zeros

    n = cl.shape[0]
    if n < 80:
        return zeros

    idx = cl.index
    rebal = _last_completed_month_end(idx)
    if rebal is None:
        return zeros

    cl_r = cl.loc[:rebal]
    if cl_r.shape[0] < 80:
        return zeros

    op = history.get('adjusted_open')
    if op is None or getattr(op, 'shape', (0, 0))[1] == 0:
        op = history.get('open')
    if op is not None:
        try:
            op = op.reindex(columns=universe).reindex(index=idx).astype(float)
            op_r = op.loc[:rebal]
        except Exception:
            op_r = cl_r.copy()
    else:
        op_r = cl_r.copy()

    on = op_r / cl_r.shift(1) - 1.0
    idr = cl_r / op_r - 1.0

    on_m = on.tail(60).mean()
    id_m = idr.tail(60).mean()

    if cl_r.shape[0] >= 6:
        ret5 = cl_r.iloc[-1] / cl_r.iloc[-6] - 1.0
    else:
        ret5 = pd.Series(0.0, index=universe, dtype=float)

    last = cl_r.iloc[-1]
    valid = last.notna() & (last > 0.0) & (cl_r.notna().sum() >= 70)
    valid = valid & on_m.notna() & id_m.notna()

    volm = history.get('volume')
    if volm is not None:
        try:
            volm = volm.reindex(columns=universe).reindex(index=idx).astype(float)
            vol_r = volm.loc[:rebal]
            dollar = (cl_r * vol_r).tail(20).median()
            liq = dollar.fillna(0.0) > 5e5
            if int(liq.sum()) >= 10:
                valid = valid & liq
        except Exception:
            pass

    el = history.get('eligible')
    if el is not None:
        try:
            el = el.reindex(columns=universe).reindex(index=idx)
            el_r = el.loc[:rebal].ffill()
            if el_r.shape[0] > 0:
                flag = el_r.iloc[-1].fillna(1.0).astype(float) > 0.5
                if int(flag.sum()) >= 10:
                    valid = valid & flag
        except Exception:
            pass

    if int(valid.sum()) < 6:
        return zeros

    z_on = _rank_centered(on_m)
    z_id = _rank_centered(id_m)
    z_rev = _rank_centered(ret5)

    score = 1.0 * z_on - 0.8 * z_id - 0.3 * z_rev
    score = score[valid].replace([np.inf, -np.inf], np.nan).dropna()

    k = int(len(score))
    if k < 6:
        return zeros

    n_side = min(50, k // 2)
    if n_side < 2:
        return zeros

    order = score.sort_values(kind='mergesort')
    shorts = order.index[:n_side]
    longs = order.index[-n_side:]

    w = min(0.5 / n_side, 0.02)

    weights = zeros.copy()
    weights.loc[longs] = w
    weights.loc[shorts] = -w

    gross = float(weights.abs().sum())
    if gross > 1.0 + 1e-12:
        weights = weights * (1.0 / gross)

    weights = weights.replace([np.inf, -np.inf], 0.0).fillna(0.0)
    return weights.astype(float)

