    R = ret.tail(_BETA_WIN)
    m = mkt.tail(_BETA_WIN).fillna(0.0)
    if len(m) < 60:
        return zeros
    counts = R.notna().sum()
    Rf = R.fillna(0.0)
    m_mean = float(m.mean())
    dm = m - m_mean
